// Runtime strings. English page: static text is in the HTML, JS-created strings come from i18n/en.js.
// Arabic page (/ar/, generated by dev/tools/render-ar.mjs) loads the full Arabic dictionary.
import EN from '../i18n/en.js';
import { html } from './env.js';

let dict = EN;
export async function loadDict() {
  if (html.lang === 'ar') dict = (await import('../i18n/ar.js')).default;
}
export function t(key, vars) {
  let s = dict[key] ?? EN[key] ?? key;
  if (vars && typeof s === 'string') s = s.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? '');
  return s;
}
